  1161	         *   失败到下一次成功重烘之间，屏上可能是新旧混合的一帧；这段时间里
  1162	         *   `rot_broken` 会**冻结跟车平移**（否则按旧 r_pan 继续挪会把新旧两种基准
  1163	         *   叠在一起，错位越滚越大）。重试间隔 ≥1200 ms，连续失败可更久。
  1164	         *   要彻底消除得双缓冲（多 152 KB PSRAM），未做。
  1165	         */
  1166	        view->rot_pending = true;
  1167	        view->rot_fail_valid = true;
  1168	        view->rot_broken = true;
  1169	        view->last_fail_ms = lv_tick_get();
  1170	        return false;
  1171	    }
  1172	
  1173	    view->r_pan_x = view->pan_dx;
  1174	    view->r_pan_y = view->pan_dy;
  1175	    view->r_rot10 = view->rot10;
  1176	    view->rot_pending = false;
  1177	    view->rot_fail_valid = false;
  1178	    view->rot_broken = false;
  1179	    /* 余量重烘/帧末重烘/增量重烘都计入同一个限频窗口。 */
  1180	    view->last_bake_ms = lv_tick_get();
  1181	    vmap_rot_place(view, 0, 0);
  1182	    vmap_rot_labels_update(view, pivot_x, pivot_y);
  1183	    lv_obj_invalidate(view->rcanvas);
  1184	    return true;
  1185	}
  1186	
  1187	/**
  1188	 * @brief 把"帧外增量还没进 R"的记账补烘掉（限频窗口内先留着）。
  1189	 *
  1190	 * @details 由 200 ms 的航向拍调用（`vmap_view_set_heading`），所以即使某次增量
  1191	 *          之后再没有任何失效，内容也会在窗口到期后的下一拍上屏；不会永远停在旧版本。
  1192	 */
  1193	static void vmap_rot_service(vmap_view_t * view)
  1194	{
  1195	    bool angle;
  1196	
  1197	    if (view == NULL || !view->heading_up) {
  1198	        return;
  1199	    }
  1200	    angle = (view->want_rot10 != view->rot10);
  1201	    if (!angle && !view->rot_pending) {
  1202	        return;
  1203	    }
  1204	    if (view->pump_phase != 0u || view->rcanvas == NULL
  1205	        || view->render_rev == 0u
  1206	        || lv_obj_has_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN)) {
  1207	        return;                 /* 帧在飞（帧末会烘）或还没显示/还没有首帧 */
  1208	    }
  1209	    if (view->last_bake_ms != 0u
  1210	        && lv_tick_elaps(view->last_bake_ms) < VMAP_ROT_BAKE_MIN_MS) {
  1211	        return;                 /* 限频窗口未到：下一拍再来 */
  1212	    }
  1213	    /*
  1214	     * 待应用角度与"帧外增量"合并到**同一次**重烘：否则先用旧角度烘一次增量会刷新
  1215	     * `last_bake_ms`，把角度请求一直挡在窗口外（持续记录时地图永远保持旧朝向）。
  1216	     * 角度**成功烘完才提交**：EPIC 旋转失败时保留 want_rot10，下一拍自动重试，
  1217	     * 不会把请求悄悄丢掉（否则静止时再没有别的东西会触发重烘）。
  1218	     */
  1219	    {
  1220	        const int32_t prev_rot10 = view->rot10;
  1221	
  1222	        /* 探针放在限频检查**之后**：这里才是真的要烘一次（之前的位置会把被窗口挡掉
  1223	         * 的重试也记成一次触发）。 */
  1224	        vmap_rot_why(angle ? 'A' : 'N');
  1225	        view->rot10 = view->want_rot10;
  1226	        if (!vmap_rot_full(view)) {
  1227	            /* 失败记账在 `vmap_rot_full()` 里统一做（见那里的注释）。 */
  1228	            view->rot10 = prev_rot10;
  1229	        }
  1230	    }
  1231	}
  1232	
  1233	/**
  1234	 * @brief 跟车：R 里的内容该位移 (-R(θ)·Δpan)；余量够只挪对象，不够重烘。
  1235	 */
  1236	static void vmap_rot_track(vmap_view_t * view)
  1237	{
  1238	    const double th = (double)view->r_rot10 * 0.1 * M_PI / 180.0;
  1239	    const double c = cos(th);
  1240	    const double s = sin(th);
  1241	    const double dpx = view->pan_dx - view->r_pan_x;
  1242	    const double dpy = view->pan_dy - view->r_pan_y;
  1243	    const int32_t sx = (int32_t)lround(-(c * dpx - s * dpy));
  1244	    const int32_t sy = (int32_t)lround(-(s * dpx + c * dpy));
  1245	    const int32_t lim = view->r_margin - VMAP_ROT_TRACK_GUARD;
  1246	
  1247	    /*
  1248	     * R 可能被写坏（上次整幅超时）：冻结平移，等一次成功重烘把 R 整体重写。
  1249	     * 否则这次位移是按"上一次成功的 r_pan"算的，而 R 里已有一段按新 pan 写入的像素。
  1250	     */
  1251	    if (view->rot_broken) {
  1252	        return;
  1253	    }
  1254	
  1255	    if (view->rot10 != view->r_rot10
  1256	        || abs((int)sx) > lim || abs((int)sy) > lim) {
  1257	        vmap_rot_why('T');
  1258	        vmap_rot_full(view);    /* 角度变了、或余量用完了；失败记账在它内部 */
  1259	        return;
  1260	    }
  1261	
  1262	    vmap_rot_place(view, sx, sy);
  1263	}
  1264	
  1265	static void vmap_view_apply_canvas_pos(vmap_view_t * view, double dx, double dy)
  1266	{
  1267	    lv_coord_t px;
  1268	    lv_coord_t py;
  1269	
  1270	    if (!view || !view->canvas) {
  1271	        return;
  1272	    }
  1273	
  1274	    /* 请求量原样记账（浮点），只有上屏这一步取整 —— 亚像素余量的唯一去处。 */
  1275	    view->pan_rx = dx;
  1276	    view->pan_ry = dy;
  1277	    px = (lv_coord_t)lround(dx);
  1278	    py = (lv_coord_t)lround(dy);
  1279	
  1280	    if (px == view->last_pan_px && py == view->last_pan_py) {
  1281	        return;
  1282	    }
  1283	
  1284	    /*
  1285	     * Moving a canvas invalidates the complete visible map. Coalesce sub-pixel
  1286	     * GNSS movement; the centered arrow still updates normally.
  1287	     */
  1288	    if (view->last_pan_px != INT32_MIN && view->last_pan_py != INT32_MIN
  1289	        && abs((int)px - view->last_pan_px) < VMAP_PAN_MIN_STEP_PX
  1290	        && abs((int)py - view->last_pan_py) < VMAP_PAN_MIN_STEP_PX) {
  1291	        return;
  1292	    }
  1293	
  1294	    view->pan_dx = (double)px;
  1295	    view->pan_dy = (double)py;
  1296	    view->last_pan_px = px;
  1297	    view->last_pan_py = py;
  1298	    view->map_rev++;
  1299	    vmap_label_collector_set_focus(&view->label_col,
  1300	        view->w / 2 + px, view->h / 2 + py);
  1301	#if defined(CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE) && CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE
  1302	    bicycle_inval_probe_tag("vmap_pan");
  1303	#endif
  1304	    /* lv_obj_set_pos already invalidates old + new areas; do not inval again. */
  1305	    /* y_bias 只加在屏幕位置上：pan_dy 与投影原点都不动，于是偏置与跟车/rebase
  1306	     * 的数学完全解耦（偏置变化既不触发重算，也不改变 rebase 时机）。 */
  1307	    if (!view->heading_up || view->heading_switch_pending) {
  1308	        lv_obj_set_pos(view->canvas,
  1309	            (lv_coord_t)(-view->margin - px),
  1310	            (lv_coord_t)(-view->margin - py + view->y_bias));
  1311	        return;
  1312	    }
  1313	
  1314	    /*
  1315	     * 航向朝上：不再让 LVGL 旋转画布（那样每次平移都要重跑一次任意角 transform，
  1316	     * 实测 60 ms/次）。改成维护一块**屏幕对齐的旋转缓冲 R**：只有角度变化或
  1317	     * 余量用完才重烘，平地跟车只移动 R 的对象（见 vmap_rot_track）。
  1318	     */
  1319	    vmap_rot_track(view);
  1320	}
