  1322	/**
  1323	 * @brief 航向朝上：地图跟随骑行方向旋转（箭头恒指上）。
  1324	 */
  1325	void vmap_view_set_heading_up(vmap_view_t * view, bool enable)
  1326	{
  1327	    if (!view || view->heading_up == enable) {
  1328	        return;
  1329	    }
  1330	
  1331	    if (enable && (view->rcanvas == NULL || view->rbuf == NULL)) {
  1332	        syslog(LOG_WARNING,
  1333	            "[map] heading-up refused: rotated buffer unavailable\n");
  1334	        return;
  1335	    }
  1336	
  1337	    view->heading_up = enable;
  1338	    view->heading_valid = false;
  1339	    view->rot10 = 0;
  1340	    view->want_rot10 = 0;
  1341	    view->r_rot10 = -1;         /* 强制下一次 track 重烘 */
  1342	    view->rot_pending = false;  /* 切换时会立刻重烘，旧的记账作废 */
  1343	
  1344	    if (enable) {
  1345	        if (view->render_rev != 0u) {
  1346	            /* 先保持正北画布 C 可见，等整幅重铺出干净底图再切 R：
  1347	             * 旧路名不会跟着转进 R，也不会和正立标签形成双影。MTP 期间
  1348	             * redraw_keep_pan 会推迟，等 MTP 结束后的帧再补。 */
  1349	            int32_t i;
  1350	
  1351	            view->heading_switch_pending = 1;
  1352	            view->heading_switch_ready = 0;
  1353	            if (view->rcanvas) {
  1354	                lv_obj_add_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
  1355	            }
  1356	            if (view->canvas) {
  1357	                lv_obj_clear_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
  1358	            }
  1359	            for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
  1360	                if (view->rot_label[i] != NULL) {
  1361	                    lv_obj_add_flag(view->rot_label[i], LV_OBJ_FLAG_HIDDEN);
  1362	                }
  1363	            }
  1364	            view->rot_label_n = 0;
  1365	            vmap_view_redraw_keep_pan(view);
  1366	        } else {
  1367	            /* 首帧：C 还没有内容，直接显示 R；首帧烘完自动补齐。 */
  1368	            if (view->rcanvas) {
  1369	                lv_obj_clear_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
  1370	            }
  1371	            if (view->canvas) {
  1372	                lv_obj_add_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
  1373	            }
  1374	        }
  1375	    } else {
  1376	        view->heading_switch_pending = 0;
  1377	        view->heading_switch_ready = 0;
  1378	        if (view->rcanvas) {
  1379	            lv_obj_add_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
  1380	        }
  1381	        if (view->canvas) {
  1382	            lv_obj_clear_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
  1383	        }
  1384	        /* 正立路名只在航向朝上时用；退回正北后由烘焙路径接管。 */
  1385	        {
  1386	            int32_t i;
  1387	
  1388	            for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
  1389	                if (view->rot_label[i] != NULL) {
  1390	                    lv_obj_add_flag(view->rot_label[i], LV_OBJ_FLAG_HIDDEN);
  1391	                }
  1392	            }
  1393	            view->rot_label_n = 0;
  1394	        }
  1395	    }
  1396	
  1397	    /* 位置公式与标签开关都变了：按新公式重摆，再整幅重来一帧。 */
  1398	    view->last_pan_px = INT32_MIN;
  1399	    view->last_pan_py = INT32_MIN;
  1400	    vmap_view_apply_canvas_pos(view, view->pan_dx, view->pan_dy);
  1401	    syslog(LOG_NOTICE, "[map] heading-up %s\n", enable ? "on" : "off");
  1402	
  1403	    /* 首帧之前不要提前开帧（开机还没进过地图时由页面层控制）。 */
  1404	    if (!enable && view->render_rev != 0u) {
  1405	        vmap_view_render(view);
  1406	    }
  1407	}
