  3161	static bool pump_tile_dirty(const vmap_view_t * view, int32_t tx, int32_t ty)
  3162	{
  3163	    const int32_t tile_size = 256;
  3164	    int32_t x1;
  3165	    int32_t y1;
  3166	    int32_t x2;
  3167	    int32_t y2;
  3168	    uint8_t i;
  3169	
  3170	    if (!view || view->pump_dirty_n == 0) {
  3171	        return true;
  3172	    }
  3173	
  3174	    x1 = (int32_t)lround((tx * tile_size - view->pump_cx) * view->scale
  3175	        + view->w / 2.0);
  3176	    y1 = (int32_t)lround((ty * tile_size - view->pump_cy) * view->scale
  3177	        + view->h / 2.0);
  3178	    x2 = (int32_t)lround(x1 + 256.0 * view->scale);
  3179	    y2 = (int32_t)lround(y1 + 256.0 * view->scale);
  3180	
  3181	    for (i = 0; i < view->pump_dirty_n; i++) {
  3182	        if (pump_rects_overlap(x1, y1, x2, y2,
  3183	                view->pump_dirty_x1[i], view->pump_dirty_y1[i],
  3184	                view->pump_dirty_x2[i], view->pump_dirty_y2[i])) {
  3185	            return true;
  3186	        }
  3187	    }
  3188	    return false;
  3189	}
