  3191	static bool pump_advance(vmap_view_t * view)
  3192	{
  3193	    view->pump_ty--;
  3194	    if (view->pump_ty < view->pump_ty_min) {
  3195	        view->pump_tx--;
  3196	        view->pump_ty = view->pump_ty_max;
  3197	    }
  3198	    return view->pump_tx >= view->pump_tx_min;
  3199	}
