  3201	static void render_begin(vmap_view_t * view, bool reset_view, bool force_clear,
  3202	    bool full_restamp)
  3203	{
  3204	    vmap_canvas_t canvas;
  3205	    const double origin_lon = reset_view ? view->lon : view->render_lon;
  3206	    const double origin_lat = reset_view ? view->lat : view->render_lat;
  3207	    int32_t sx;
  3208	    int32_t sy;
  3209	    bool scrolled = false;
  3210	
  3211	    /* 先置"帧在飞"再做任何 C 修改：期间的位置更新不能烘半成品。
  3212	     * 两条路径（reset_view / keep-pan）都必须置位，否则泵不会推进。 */
  3213	    view->pump_phase = 1;
  3214	    view->pump_need_region = 1;
  3215	    /* 这一帧是不是 keep-pan 整幅重铺：瓦片失败填底色、航向切换都靠它。 */
  3216	    view->restamp_full_active = full_restamp ? 1u : 0u;
  3217	
  3218	    /* fopen/.vpk index belongs on the first pump tick, not GNSS/REC/set_view. */
  3219	
  3220	    vmap_perf_frame_begin();
  3221	    VMAP_PERF_T0();
  3222	    dvfs_map_busy(true);
  3223	    view->pump_dirty_n = 0;
  3224	    sx = (view->last_pan_px == INT32_MIN) ? (int32_t)lround(view->pan_dx)
  3225	                                         : view->last_pan_px;
  3226	    sy = (view->last_pan_py == INT32_MIN) ? (int32_t)lround(view->pan_dy)
  3227	                                         : view->last_pan_py;
  3228	
  3229	    if (reset_view) {
  3230	        /*
  3231	         * A hidden page can jump much farther than the last on-screen pan.\…1291 tokens truncated…33	        view->w / 2 + (int32_t)lround(view->pan_dx),
  3334	        view->h / 2 + (int32_t)lround(view->pan_dy));
  3335	
  3336	    /* 浮点投影原点：与滚动后的像素同一网格（整数部分已滚走，小数留在这里）。 */
  3337	    vmap_latlong_to_pixel_d(view->render_lat, view->render_lon, view->zoom,
  3338	        &view->pump_cx_d, &view->pump_cy_d);
  3339	    view->pump_cx = (int)lround(view->pump_cx_d);
  3340	    view->pump_cy = (int)lround(view->pump_cy_d);
  3341	    /*
  3342	     * ring=0（2026-10-27，对齐 X-TRACK 的 tile rect 语义）：
  3343	     * 画布本身已经带了 margin 的 overscan，再往外加一圈瓦片只会选到**完全落在
  3344	     * 画布之外**的瓦片 —— 近边不超过画布边，`vmap_render_draw_tile` 的像素写入
  3345	     * 与 `label_pan_canvas_bounds()` 的标签收集都会把它们裁掉，却仍然要付要素
  3346	     * 遍历（道路层还要按 class 扫 14 遍）和首帧的闪存读。
  3347	     * 代价还落在节拍上：泵每 20 ms 只画 2 张，且从 (tx_max,ty_max) 开始扫，
  3348	     * 多出来的一圈排在**可见区域之前**。实测几何（240x216 视口、margin 128、
  3349	     * scale 1.69）是 16~20 张里只有 4~6 张与画布相交。
  3350	     */
  3351	    tile_range(view->pump_cx, view->pump_cy, view->w, view->h, view->scale, 0,
  3352	        &view->pump_tx_min, &view->pump_ty_min,
  3353	        &view->pump_tx_max, &view->pump_ty_max);
  3354	    if (full_restamp) {
  3355	        /* 取整原点与绘制的浮点原点可能差 1 像素；整幅重铺多画一圈边瓦片，
  3356	         * 保证 C 的四边也被瓦片（或失败时的底色填充）覆盖。 */
  3357	        view->pump_tx_min--;
  3358	        view->pump_ty_min--;
  3359	        view->pump_tx_max++;
  3360	        view->pump_ty_max++;
  3361	    }
  3362	    view->pump_tx = view->pump_tx_max;
  3363	    view->pump_ty = view->pump_ty_max;
  3364	
  3365	    if (scrolled) {
  3366	        syslog(LOG_INFO,
  3367	            "[map] rebase scroll=%d,%d dirty=%u labels=%d z=%d",
  3368	            (int)sx, (int)sy, (unsigned)view->pump_dirty_n,
  3369	            (int)view->label_col.retained_count, view->zoom);
  3370	    }
  3371	    VMAP_PERF_T1(begin);
  3372	}
