   849	static void tile_range(int32_t center_x, int32_t center_y, int32_t canvas_w,
   850	    int32_t canvas_h, double scale, int32_t ring,
   851	    int32_t * tx_min, int32_t * ty_min, int32_t * tx_max, int32_t * ty_max)
   852	{
   853	    const int32_t tile_size = 256;
   854	    double half_w = (canvas_w / 2.0) / scale;
   855	    double half_h = (canvas_h / 2.0) / scale;
   856	    double pad = (double)ring * tile_size;
   857	    double left = (double)center_x - half_w - pad;
   858	    double top = (double)center_y - half_h - pad;
   859	    double right = (double)center_x + half_w + pad;
   860	    double bottom = (double)center_y + half_h + pad;
   861	
   862	    *tx_min = (int32_t)(left / tile_size) - (left < 0 ? 1 : 0);
   863	    *ty_min = (int32_t)(top / tile_size) - (top < 0 ? 1 : 0);
   864	    *tx_max = (int32_t)(right / tile_size);
   865	    *ty_max = (int32_t)(bottom / tile_size);
   866	}
