  1444	void vmap_view_set_heading(vmap_view_t * view, float heading_deg, float speed_kph)
  1445	{
  1446	    double d = (double)heading_deg;
  1447	    int32_t target;
  1448	    int32_t delta;
  1449	
  1450	    if (!view || !view->canvas) {
  1451	        return;
  1452	    }
  1453	    if (!view->heading_up) {
  1454	        return;
  1455	    }
  1456	    if (!(d >= 0.0) || !(d < 360.0)) {
  1457	        /* NaN / 越界：角度不动，但帧外增量的记账照样要服务。 */
  1458	        vmap_rot_service(view);
  1459	        return;
  1460	    }
  1461	
  1462	    if (!view->heading_valid) {
  1463	        /* 首个航向无条件接受：否则停车时箭头指上、地图还是正北。 */
  1464	        view->heading_deg = d;
  1465	        view->heading_valid = true;
  1466	    } else if (speed_kph >= VMAP_ROT_MIN_KPH) {
  1467	        double diff = d - view->heading_deg;
  1468	
  1469	        /* 圆周低通：先把差值折到 -180..180，避免 359°→1° 绕一整圈。 */
  1470	        while (diff > 180.0) {
  1471	            diff -= 360.0;
  1472	        }
  1473	        while (diff < -180.0) {
  1474	            diff += 360.0;
  1475	        }
  1476	        view->heading_deg += diff * (double)VMAP_ROT_SMOOTH;
  1477	        while (view->heading_deg >= 360.0) {
  1478	            view->heading_deg -= 360.0;
  1479	        }
  1480	        while (view->heading_deg < 0.0) {
  1481	            view->heading_deg += 360.0;
  1482	        }
  1483	    } else {
  1484	        /* 低速：course 是噪声，保持上次朝向；增量仍要走服务拍。 */
  1485	        vmap_rot_service(view);
  1486	        return;
  1487	    }
