  1548	static void route_note_box(lv_area_t * box, int32_t x1, int32_t y1, int32_t x2,
  1549	    int32_t y2)
  1550	{
  1551	    if (x1 > x2) {
  1552	        const int32_t t = x1;
  1553	
  1554	        x1 = x2;
  1555	        x2 = t;
  1556	    }
