  1569	static void route_paint_geo_range(const vmap_view_t * view, vmap_canvas_t * canvas,
  1570	    const vmap_route_pt_t * pts, const float * along, uint32_t begin, uint32_t end,
  1571	    double extra_lon, double extra_lat, double extra_along, bool extra_first,
  1572	    uint16_t rgb565)
  1573	{
  1574	    vmap_point_t px[256];
  1575	    vmap_point_t chev[VMAP_ROUTE_CHEVRON_MAX];
  1576	    double chev_ang[VMAP_ROUTE_CHEVRON_MAX];
  1577	    int32_t chev_n = 0;
  1578	    double prev_along = 0.0;
  1579	    double next_mark = 0.0;
  1580	    int32_t start_x = 0;
  1581	    int32_t start_y = 0;
  1582	    bool have_start = false;
  1583	    int32_t n = 0;
  1584	    uint32_t i;
  1585	
  1586	    if (!view || !canvas || !pts || end < 2u || begin + 1u > end) {
  1587	        return;
  1588	    }
  1589	
  1590	    lv_area_t new_box = { INT32_MAX, INT32_MAX, INT32_MIN, INT32_MIN };
  1591	    const bool chevrons = extra_first && along != NULL;
  1592	
  1593	    if (extra_first) {
  1594	        route_append_geo(view, px, &n, (int32_t)(sizeof(px) / sizeof(px[0])),
  1595	            extra_lon, extra_lat, true);
  1596	        if (n > 0) {
  1597	            /* 分块落线会覆盖 px[0]；骑手投影点先单独留一份给跳变记账。 */
  1598	            start_x = px[0].x;
  1599	            start_y = px[0].y;
  1600	            have_start = true;
  1601	        }
  1602	    }
  1603	
  1604	    if (chevrons) {
  1605	        prev_along = extra_along;
  1606	        next_mark = ceil(prev_along / VMAP_ROUTE_CHEVRON_STEP_M)
  1607	            * VMAP_ROUTE_CHEVRON_STEP_M;
  1608	        if (next_mark <= prev_along) {
  1609	            next_mark += VMAP_ROUTE_CHEVRON_STEP_M;
  1610	        }
  1611	    } else if (along != NULL && begin > 0u) {
  1612	        prev_along = (double)along[begin - 1u];
  1613	    }
  1614	
  1615	    for (i = begin; i < end; i++) {
  1616	        const bool last = (i + 1u == end);
  1617	        const int32_t before = n;
  1618	
  1619	        route_append_geo(view, px, &n, (int32_t)(sizeof(px) / sizeof(px[0])),
  1620	            pts[i].lon, pts[i].lat, last);
  1621	
  1622	        if (!have_start && n > before) {
  1623	            /* 骑手投影点被范围检查拒绝时的兜底：用第一个真正落线的点当分割点，
  1624	             * 同时把里程基准挪到它身上，避免不可见区段的 ^ 挤到第一段上。 */
  1625	            start_x = px[n - 1].x;
  1626	            start_y = px[n - 1].y;
  1627	            have_start = true;
  1628	            if (chevrons && along != NULL) {
  1629	                prev_along = (double)along[i];
  1630	                next_mark = ceil(prev_along / VMAP_ROUTE_CHEVRON_STEP_M)
  1631	                    * VMAP_ROUTE_CHEVRON_STEP_M;
  1632	                if (next_mark <= prev_along) {
  1633	                    next_mark += VMAP_ROUTE_CHEVRON_STEP_M;
  1634	                }
  1635	            }
  1636	        }
  1637	
  1638	        if (n > before && n >= 2) {
  1639	            const int32_t k = n - 1;
  1640	            const double dx = (double)(px[k].x - px[k - 1].x);
  1641	            const double dy = (double)(px[k].y - px[k - 1].y);
  1642	            const double seg_m = (along != NULL) ? (double)along[i] - prev_along
  1643	                                                 : 0.0;
  1644	
  1645	            /* ^ 按沿路线里程取（不是点序号）：稀疏 GPX / 路网路线点距变化很大，
  1646	             * 点序号会把 ^ 拉成几百米一个；里程基准与绘制起点无关，重绘幂等。 */
