  1674	                px[0] = px[n - 1];
  1675	                n = 1;
  1676	            }
  1677	        }
  1678	    }
  1679	
  1680	    route_stroke_px(canvas, px, n, rgb565);
  1681	
  1682	    /* ^ 画在蓝线之后：黑/橙两臂压在蓝线上才看得清（原来先画线后画 ^，
  1683	     * 线把 ^ 的中心盖掉了）。 */
  1684	    for (i = 0; i < (uint32_t)chev_n; i++) {
  1685	        route_draw_chevron(canvas, chev[i].x, chev[i].y, chev_ang[i]);
  1686	        route_note_box(&new_box, chev[i].x - VMAP_ROUTE_CHEVRON_ARM_PX,
  1687	            chev[i].y - VMAP_ROUTE_CHEVRON_ARM_PX,
  1688	            chev[i].x + VMAP_ROUTE_CHEVRON_ARM_PX,
  1689	            chev[i].y + VMAP_ROUTE_CHEVRON_ARM_PX);
  1690	    }
  1691	
  1692	    if (extra_first && have_start && new_box.x2 >= new_box.x1) {
  1693	        /* 分割点跳变判定：以路线起点（骑手位置投影）为准，阈值取半个屏宽 ——
  1694	         * 小于它的移动都属于跟车滚动，滚动脏条已经覆盖。 */
  1695	        const int32_t sx = start_x;
  1696	        const int32_t sy = start_y;
  1697	        int32_t jx = sx - s_route_split_x;
  1698	        int32_t jy = sy - s_route_split_y;
  1699	
  1700	        if (jx < 0) {
  1701	            jx = -jx;
  1702	        }
  1703	        if (jy < 0) {
  1704	            jy = -jy;
  1705	        }
  1706	        if (s_route_box_valid && (jx > 120 || jy > 120)) {
  1707	            vmap_view_invalidate_canvas_area(view, s_route_box.x1, s_route_box.y1,
  1708	                s_route_box.x2, s_route_box.y2);
  1709	        }
  1710	        if (new_box.x2 >= new_box.x1) {
  1711	            s_route_box = new_box;
  1712	            s_route_box_valid = true;
  1713	        }
  1714	        s_route_split_x = sx;
  1715	        s_route_split_y = sy;
  1716	    }
  1717	}
